> @@ -2529,6 +2539,31 @@ static const struct snd_soc_dapm_route wsa_audio_map[] = {
>  	{"WSA_SPK2 OUT", NULL, "WSA_MCLK"},
>  };
>  
> +static const struct snd_soc_dapm_route wsa_audio_map_v2_5[] = {
> +	{"WSA RX4 MUX", "AIF1_PB", "WSA AIF1 PB"},
